using LedgerFlow.Api.Data;using LedgerFlow.Api.Models;using LedgerFlow.Api.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace LedgerFlow.Api.Controllers;[ApiController,Route("api/transactions")]public sealed class TransactionsController(AppDbContext db,ReconciliationService reconciliation):ControllerBase{[HttpGet]public async Task<ActionResult<IReadOnlyList<Transaction>>>List([FromQuery]TransactionStatus? status,[FromQuery]string? query,CancellationToken ct){var q=db.Transactions.AsNoTracking().OrderByDescending(x=>x.BookedAt).AsQueryable();if(status is not null)q=q.Where(x=>x.Status==status);if(!string.IsNullOrWhiteSpace(query))q=q.Where(x=>x.Reference.Contains(query)||x.Account.Contains(query));return Ok(await q.Take(200).ToListAsync(ct));}[HttpPost("{id:guid}/reconcile")]public async Task<ActionResult<Transaction>>Reconcile(Guid id,CancellationToken ct){var transaction=await db.Transactions.SingleOrDefaultAsync(x=>x.Id==id,ct);if(transaction is null)return NotFound();var result=reconciliation.Evaluate(transaction);transaction.Status=result.Status;transaction.Reason=result.Reason;db.AuditEvents.Add(new AuditEvent{EntityType=nameof(Transaction),EntityId=id.ToString(),Action="Reconciled",Detail=result.Reason});await db.SaveChangesAsync(ct);return Ok(transaction);}}
